export type ParsedRequestLineInstruction<
  TProgram extends string = typeof ELOTE_POOL_PROGRAM_ADDRESS,
  TAccountMetas extends readonly AccountMeta[] = readonly AccountMeta[],
> = {
  programAddress: Address<TProgram>;
  accounts: {
    borrower: TAccountMetas[0];
    /**
     * Funds the request and receives the rent back on withdraw or reject; never the borrower's
     * concern.
     */
    payer: TAccountMetas[1];
    /** The sponsor named in the terms; required (and signing) when one is named. */
    sponsor?: TAccountMetas[2] | undefined;
    pool: TAccountMetas[3];
    line: TAccountMetas[4];
    systemProgram: TAccountMetas[5];
    eventAuthority: TAccountMetas[6];
    program: TAccountMetas[7];
  };
  data: RequestLineInstructionData;
};

export function parseRequestLineInstruction<
  TProgram extends string,
  TAccountMetas extends readonly AccountMeta[],
>(
  instruction: Instruction<TProgram> &
    InstructionWithAccounts<TAccountMetas> &
    InstructionWithData<ReadonlyUint8Array>,
): ParsedRequestLineInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 8) {
    throw new SolanaError(
      SOLANA_ERROR__PROGRAM_CLIENTS__INSUFFICIENT_ACCOUNT_METAS,
      {
        actualAccountMetas: instruction.accounts.length,
        expectedAccountMetas: 8,
      },
    );
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  const getNextOptionalAccount = () => {
    const accountMeta = getNextAccount();
    return accountMeta.address === ELOTE_POOL_PROGRAM_ADDRESS
      ? undefined
      : accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      borrower: getNextAccount(),
      payer: getNextAccount(),
      sponsor: getNextOptionalAccount(),
      pool: getNextAccount(),
      line: getNextAccount(),
      systemProgram: getNextAccount(),
      eventAuthority: getNextAccount(),
      program: getNextAccount(),
    },
    data: getRequestLineInstructionDataDecoder().decode(instruction.data),
  };
}
